/* Device-local community prototype. No real people, submissions or reward credits. */
(() => {
'use strict';
const app=window.MONPERKS_APP,{esc,toast,modal,closeModal}=app;
const $=s=>document.querySelector(s),catalog=app.getCatalog(),key='monperks-community-v1';
const channels=[['all','全部话题'],['tips','省钱攻略'],['deals','优惠情报'],['chat','购物讨论'],['web3','Web3 入门']];
const fresh=()=>({v:1,name:'好发现探索者',bio:'收集小确幸，也分享好发现。',avatar:'lavender',followed:[],votes:[],saved:[],hidden:[],posts:[],comments:{},reports:[],notifications:[],tab:'for-you'});
function load(){try{const x=JSON.parse(localStorage.getItem(key));if(x?.v===1&&['followed','votes','saved','hidden','posts','reports','notifications'].every(k=>Array.isArray(x[k]))&&x.comments&&typeof x.name==='string')return x}catch{}return fresh()}
let state=load(),tab=state.tab||'for-you',channel='all',query='',count=5,brandQuery='';
const seeds=[
 {id:'seed-nike',author:'MONPERKS 编辑部',avatar:'purple',label:'编辑精选 · 示例',channel:'deals',brand:'nike',title:'新装备不一定要原价，运动清单先收藏。',body:'最近在整理适合日常跑步的装备清单。比起只看折扣，我更在意尺码、退换条款和适用商品。\n这张示例优惠卡把关键信息放在一起，点开就能看清。你挑运动鞋最看重什么？',likes:24,at:'2026-10-17T03:00:00Z',pinned:true},
 {id:'seed-weekend',author:'周末出逃计划',avatar:'mint',label:'社区样例',channel:'tips',brand:'trip',title:'订酒店前，我一定会检查的 3 件事。',body:'① 对比含税总价，不只看首页价格。\n② 留意免费取消截止时间与酒店当地时区。\n③ 确认优惠券是否限制房型、日期或新用户。\n省钱的前提，是选到真正适合自己的方案。',likes:18,at:'2026-10-17T02:10:00Z'},
 {id:'seed-notion',author:'灵感收纳员',avatar:'peach',label:'社区样例',channel:'chat',brand:'notion',title:'你会为了一个功能，升级一整年的订阅吗？',body:'最近在重新整理自己的软件订阅。我的原则是先用免费版跑通需求，再判断是否需要付费。\n想听听大家：哪些工具值得长期订阅，哪些只是偶尔会用？',likes:12,at:'2026-10-16T09:20:00Z'},
 {id:'seed-monad',author:'MONPERKS 小课堂',avatar:'purple',label:'产品说明 · 示例',channel:'web3',brand:null,title:'连接钱包之后，我的积分就上链了吗？',body:'还没有。钱包连接只是让页面知道你的公开地址，和签名登录、链上转账是不同步骤。\n当前积分和兑换都是演示。正式奖励需要服务端确认商家结算，再由已充值的 Monad 合约发放。发现星不能兑换 USDT。',likes:31,at:'2026-10-16T06:40:00Z'},
 {id:'seed-desk',author:'桌面生活家',avatar:'blue',label:'社区样例',channel:'deals',brand:'amazon',title:'给桌面做减法，先从真正需要的那一件开始。',body:'不一定要换一整套设备。一副舒适的耳机、顺手的键盘，也能让工作日更舒服。\n看看示例数码优惠，再想一想：这是实际需求，还是被折扣说服了？',likes:9,at:'2026-10-15T11:00:00Z'},
 {id:'seed-green',author:'慢慢生活日记',avatar:'mint',label:'社区样例',channel:'tips',brand:'iherb',title:'优惠码之外，还要留意运费和起送门槛。',body:'凑单之前先算一遍实际支出。为了省运费多买不需要的东西，有时反而更贵。\n我的小习惯：先列购物清单，再去找券。你有什么一直在用的省钱方法？',likes:16,at:'2026-10-15T05:00:00Z'}
];
const sampleComments={'seed-nike':[{id:'c-nike-1',name:'跑步的橘子',text:'我会先看脚感和退换政策，再决定是否用券。',at:'2026-10-17T03:20:00Z',sample:true}],'seed-weekend':[{id:'c-trip-1',name:'留一张车票',text:'含税总价真的很重要，取消条款也要截图留存。',at:'2026-10-17T03:15:00Z',sample:true}]};
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true}catch{toast('社区数据未能保存，当前修改仅在此页面有效');return false}}
function notify(title,body,target='dashboard'){state.notifications.unshift({id:crypto.randomUUID(),title,body,target,read:false,at:new Date().toISOString()});state.notifications=state.notifications.slice(0,60)}
const all=()=>[...state.posts,...seeds];
const get=id=>all().find(p=>p.id===id);
const comments=id=>[...(sampleComments[id]||[]),...(state.comments[id]||[])];
const time=at=>new Date(at).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit'});
const channelName=id=>channels.find(c=>c[0]===id)?.[1]||'购物讨论';
const avatar=(name,color='lavender')=>`<span class="community-avatar ${['purple','mint','peach','blue','lavender'].includes(color)?color:'lavender'}">${esc(name.slice(0,1))}</span>`;
const isFollowed=id=>state.followed.includes(id);
function followButton(id,small=false){const yes=isFollowed(id);return `<button class="follow-button ${yes?'is-following':''} ${small?'compact':''}" data-community="follow" data-id="${esc(id)}" aria-pressed="${yes}">${yes?'已关注 ✓':'+ 关注'}</button>`}
function author(p){return p.mine?state.name:p.author}
function postCard(p,detail=false){const user=author(p),brand=catalog.find(o=>o.id===p.brand),n=comments(p.id).length;return `<article class="community-post" data-post-id="${esc(p.id)}"><div class="post-header">${avatar(user,p.mine?state.avatar:p.avatar)}<div class="post-author"><strong>${esc(user)}</strong><small>${time(p.at)} · ${p.mine?'本机发布':esc(p.label)}</small></div>${p.pinned?'<span class="pinned-tag">✦ 编辑精选</span>':''}<button class="post-more" data-community="${p.mine?'manage':'report'}" data-id="${esc(p.id)}" aria-label="${p.mine?'管理动态':'举报动态'}">···</button></div><div class="post-channel"># ${channelName(p.channel)}</div><h2 class="post-title">${detail?esc(p.title):`<button data-community="detail" data-id="${esc(p.id)}">${esc(p.title)}</button>`}</h2><p class="post-copy">${esc(p.body)}</p>${p.link?`<a class="post-source" href="${esc(p.link)}" target="_blank" rel="noopener noreferrer nofollow ugc">查看分享链接 ↗ <span>外部网站</span></a>`:''}${brand?`<div class="post-offer" style="--offer-tint:${brand.bg}"><span class="post-offer-logo" style="background:${brand.color}">${brand.symbol}</span><div><small>关联优惠 · 示例</small><strong>${brand.brand} · ${brand.discount.replace(/\n/g,' ')}</strong><span>${brand.title}</span></div><button data-action="offer" data-id="${brand.id}" aria-label="查看 ${brand.brand} 关联优惠">↗</button></div>`:''}<div class="post-actions"><button class="${state.votes.includes(p.id)?'selected':''}" data-community="vote" data-id="${esc(p.id)}" aria-pressed="${state.votes.includes(p.id)}">♧ <span>实用</span> <b>${(p.likes||0)+(state.votes.includes(p.id)?1:0)}</b></button><button data-community="detail" data-id="${esc(p.id)}">◯ <span>评论</span> <b>${n}</b></button><button class="${state.saved.includes(p.id)?'selected':''}" data-community="bookmark" data-id="${esc(p.id)}" aria-pressed="${state.saved.includes(p.id)}">${state.saved.includes(p.id)?'♥':'♡'} <span>${state.saved.includes(p.id)?'已收藏':'收藏'}</span></button><button data-community="share" data-id="${esc(p.id)}" aria-label="分享动态链接">↗</button></div>${!detail&&n?`<button class="comment-preview" data-community="detail" data-id="${esc(p.id)}"><strong>${esc(comments(p.id)[0].name)}</strong>：${esc(comments(p.id)[0].text.slice(0,68))}<span>查看讨论 →</span></button>`:''}</article>`}
function rail(){const p=app.page(),s=app.getState();return `<aside class="community-rail"><div class="rail-title">MY LITTLE WORLD</div><a class="rail-item ${p==='feed'?'active':''}" href="#feed"><span>▦</span> 社区动态 <small>NEW</small></a><a class="rail-item ${p==='discover'?'active':''}" href="#discover"><span>⌕</span> 发现优惠</a><a class="rail-item ${p==='brands'?'active':''}" href="#brands"><span>◇</span> 品牌广场</a><a class="rail-item ${p==='earn'?'active':''}" href="#earn"><span>✦</span> 奖励中心</a><a class="rail-item ${p==='dashboard'?'active':''}" href="#dashboard"><span>▱</span> 我的工作台</a><a class="rail-item" href="#saved"><span>♡</span> 优惠收藏</a><div class="rail-divider"></div><div class="rail-title">YOUR SPACE</div><button class="rail-item" data-community="notifications"><span>◷</span> 通知中心 <b class="notification-count">${state.notifications.filter(n=>!n.read).length||''}</b></button><a class="rail-item" href="#settings"><span>⚙</span> 个人设置</a><div class="rail-profile">${avatar(state.name,state.avatar)}<strong>${esc(state.name)}</strong><p>${esc(state.bio)}</p><span>${state.followed.length} 关注品牌 <i>·</i> ${state.posts.length} 本机动态</span><a href="#dashboard">查看我的空间 ↗</a></div><div class="rail-points"><span>YOUR PERKS</span><strong>${s.points.toLocaleString()} <small>✦</small></strong><p>演示积分，和好发现一起积累。</p><a href="#wallet">前往积分钱包 ↗</a></div></aside>`}
function side(){return `<aside class="community-right"><section class="community-widget"><div class="widget-title"><h3>值得关注的品牌</h3><a href="#brands">全部 ↗</a></div>${catalog.slice(0,4).map(o=>`<div class="brand-follow-row"><span class="merchant-symbol" style="--merchant-color:${o.color}">${o.symbol}</span><div><strong>${o.brand}</strong><small>${channels[1][1]} · 示例品牌</small></div>${followButton(o.id,true)}</div>`).join('')}</section><section class="community-widget topic-widget"><div class="widget-title"><h3>今天聊点什么？</h3><span>示例话题</span></div>${[['tips','购物前，你会先比价吗？'],['chat','分享你的年度好物'],['web3','第一次连接 Web3 钱包']].map(([id,title],i)=>`<button data-community="topic" data-id="${id}"><b>0${i+1}</b><div><strong>${title}</strong><small># ${channelName(id)}</small></div><span>↗</span></button>`).join('')}</section><section class="community-widget community-guidelines"><span class="guideline-star">✳</span><h3>让好发现，<br>带来好交流。</h3><p>分享真实体验，标明信息来源。<br>不发布私钥，不承诺收益。</p><button data-community="guidelines">查看社区约定 ↗</button></section><div class="community-ad"><span>SPONSORED SPACE</span><strong>好品牌，值得被发现。</strong><button data-action="partners">品牌合作与广告展示 ↗</button><small>广告位预留 · 不因互动发放提现积分</small></div></aside>`}
function layout(content,right=true){return `<section class="container community-layout ${right?'':'two-column'}">${rail()}<div class="community-main">${content}</div>${right?side():''}</section>`}
function feed(){return layout(`<div class="feed-heading"><div><p class="section-kicker">GOOD FINDS, SHARED</p><h1>打开生活的另一种可能<span>✳</span></h1><p>优惠之外，也有值得分享的经验与灵感。</p></div><button class="button" data-community="compose">＋ 发布动态</button></div><div class="feed-welcome"><div><span>YOUR COMMUNITY, YOUR PACE</span><h2>一个人找优惠。<br>一群人，发现更多。</h2><p>关注喜欢的品牌，让好发现来到你的动态里。</p><a href="#brands">探索品牌广场 ↗</a></div><div class="welcome-orbit"><span>✦</span><b>好发现<br>一起分享</b><i>♡</i></div></div><div class="feed-demo-note"><span>ⓘ</span><p>社区演示：作者、历史互动及内容为示例。你的发布、评论与关注仅保存在本设备，不对外发送。</p></div><button class="feed-compose-prompt" data-community="compose">${avatar(state.name,state.avatar)}<span>今天发现了什么好优惠？</span><b>分享一下 ↗</b></button><div class="feed-controls"><div class="feed-tabs" role="group" aria-label="动态范围">${[['for-you','为你推荐'],['latest','最新发布'],['following','我的关注'],['bookmarks','已收藏']].map(([id,name])=>`<button data-community="tab" data-id="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${name}</button>`).join('')}</div><label class="feed-search"><span>⌕</span><input id="feed-search" aria-label="搜索社区动态" type="search" value="${esc(query)}" placeholder="搜索动态…" maxlength="80"></label></div><div class="feed-topics" role="group" aria-label="社区话题">${channels.map(([id,name])=>`<button data-community="topic" data-id="${id}" class="${channel===id?'active':''}" aria-pressed="${channel===id}">${id==='all'?'':'# '}${name}</button>`).join('')}</div><div id="community-stream"></div><button class="button light feed-load" id="feed-more" data-community="more">发现更多讨论 ↓</button>`)}
function filtered(){let list=all().filter(p=>!state.hidden.includes(p.id)&&(channel==='all'||channel===p.channel)&&(!query||`${p.title} ${p.body} ${author(p)} ${catalog.find(o=>o.id===p.brand)?.brand||''}`.toLowerCase().includes(query.toLowerCase())));if(tab==='following')list=list.filter(p=>p.brand&&state.followed.includes(p.brand));if(tab==='bookmarks')list=list.filter(p=>state.saved.includes(p.id));if(tab==='latest')list.sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));else list.sort((a,b)=>(b.mine?3:b.pinned?2:0)-(a.mine?3:a.pinned?2:0)||Date.parse(b.at)-Date.parse(a.at));return list}
function renderStream(){const target=$('#community-stream');if(!target)return;const list=filtered();target.innerHTML=list.length?list.slice(0,count).map(p=>postCard(p)).join(''):`<div class="empty-state"><span>${tab==='following'?'◇':tab==='bookmarks'?'♡':'⌕'}</span><h3>${tab==='following'?'关注之后，好发现就会来。':tab==='bookmarks'?'把值得再看的讨论，留在这里。':'暂时没有找到相关动态。'}</h3><p>${tab==='following'?'去品牌广场关注你喜欢的品牌。':'试试其他话题，或分享你的第一条动态。'}</p><a class="button small" href="#brands">发现品牌 ↗</a></div>`;$('#feed-more').hidden=list.length<=count}
function refresh(){app.render()}
function follow(id){if(!catalog.some(o=>o.id===id))return;const i=state.followed.indexOf(id);if(i>=0)state.followed.splice(i,1);else{state.followed.push(id);notify('关注成功',`已关注 ${catalog.find(o=>o.id===id).brand}，可以在「我的关注」筛选相关动态。`,'feed')}save();refresh();toast(i>=0?'已取消关注':'已关注品牌，相关动态可在「我的关注」查看')}
function compose(existing){const p=existing||{};modal(`<p class="modal-eyebrow">SHARE A LITTLE GOOD</p><h2 class="modal-title">${existing?'编辑你的好发现':'分享一份好发现。'}</h2><p class="modal-description">只保存在此设备。分享不产生积分或对外发布。</p><form id="community-compose" data-edit-id="${esc(p.id||'')}"><div class="field"><label for="post-title">一个清楚的标题</label><input id="post-title" maxlength="80" minlength="4" required placeholder="例如：订酒店前，值得检查的三件事" value="${esc(p.title||'')}"></div><div class="field"><label for="post-body">分享你的发现</label><textarea id="post-body" maxlength="2000" minlength="10" required placeholder="优惠亮点、使用条件、购物经验…">${esc(p.body||'')}</textarea><small>不发布个人敏感信息、私钥或保证收益的承诺。</small></div><div class="compose-row"><div class="field"><label for="post-channel">选择话题</label><select id="post-channel">${channels.slice(1).map(([id,name])=>`<option value="${id}" ${p.channel===id?'selected':''}>${name}</option>`).join('')}</select></div><div class="field"><label for="post-brand">关联品牌（可选）</label><select id="post-brand"><option value="">不关联</option>${catalog.map(o=>`<option value="${o.id}" ${p.brand===o.id?'selected':''}>${o.brand}</option>`).join('')}</select></div></div><div class="field"><label for="post-link">来源链接（可选）</label><input id="post-link" type="url" maxlength="500" placeholder="https://…" value="${esc(p.link||'')}"></div><p class="form-error" id="compose-error" role="alert"></p><button class="button wide" type="submit">${existing?'保存修改':'发布到本机动态'} ↗</button></form>`)}
function detail(id){const p=get(id);if(!p)return;const rows=comments(id);modal(`<div class="post-detail">${postCard(p,true)}<div class="discussion-heading"><h3>一起聊聊 <span>${rows.length}</span></h3><small>示例 / 本机讨论</small></div><div class="discussion-list">${rows.length?rows.map(c=>`<div class="discussion-comment">${avatar(c.mine?state.name:c.name,c.mine?state.avatar:'mint')}<div><strong>${esc(c.mine?state.name:c.name)} <small>${c.sample?'示例评论':'本机评论'}</small></strong><p>${esc(c.text)}</p><span>${time(c.at)}</span></div>${c.mine?`<button data-community="remove-comment" data-post="${esc(id)}" data-id="${esc(c.id)}" aria-label="撤回我的评论">撤回</button>`:''}</div>`).join(''):'<p class="no-comments">还没有讨论，分享你的想法吧。</p>'}</div><form id="community-comment" data-post-id="${esc(id)}"><label class="sr-only" for="comment-text">评论内容</label><textarea id="comment-text" required minlength="2" maxlength="500" placeholder="理性讨论，分享真实体验…"></textarea><div><small>仅本设备保存 · 不发放积分</small><button class="button small" type="submit">发表评论 ↗</button></div><p class="form-error" id="comment-error" role="alert"></p></form></div>`);$('#modal').classList.add('community-dialog')}
function brandPage(){const filteredBrands=catalog.filter(o=>!brandQuery||o.brand.toLowerCase().includes(brandQuery.toLowerCase()));return layout(`<div class="feed-heading"><div><p class="section-kicker">FIND YOUR FAVORITES</p><h1>好品牌，慢慢发现。</h1><p>关注感兴趣的品牌，为自己的动态加一点偏爱。</p></div></div><label class="search-box brand-search"><span>⌕</span><input id="brand-search" type="search" placeholder="搜索品牌名称…" aria-label="搜索品牌" value="${esc(brandQuery)}" maxlength="80"></label><div class="brand-directory">${filteredBrands.length?filteredBrands.map(o=>`<article class="brand-directory-card"><div class="brand-cover" style="background:${o.bg}"><span class="directory-symbol" style="color:${o.color}">${o.symbol}</span><span class="demo-tiny">示例品牌</span></div><div class="brand-directory-body"><div><h2>${o.brand}</h2>${followButton(o.id)}</div><p>${o.subtitle}</p><span>1 个示例优惠 · ${seeds.filter(p=>p.brand===o.id).length} 条示例动态</span><div><button class="text-button" data-action="offer" data-id="${o.id}">查看优惠 ↗</button><button class="text-button" data-community="brand-feed" data-id="${o.id}">相关讨论 →</button></div></div></article>`).join(''):'<div class="empty-state"><span>⌕</span><h3>没有找到这个品牌</h3><p>试试其他名称。</p></div>'}</div>`,false)}
function dashboard(){const s=app.getState(),own=state.posts.filter(p=>!state.hidden.includes(p.id));return layout(`<div class="profile-cover"><div class="profile-cover-pattern">✳</div>${avatar(state.name,state.avatar)}<h1>${esc(state.name)}</h1><p>${esc(state.bio)}</p><span>MY LITTLE COLLECTION · 本机个人空间</span><a class="button light small" href="#settings">编辑资料 ↗</a></div><div class="community-metrics"><div><strong>${own.length}</strong><span>我的动态</span></div><div><strong>${state.followed.length}</strong><span>关注品牌</span></div><div><strong>${state.saved.length}</strong><span>收藏讨论</span></div><div><strong>${s.saved.length}</strong><span>收藏优惠</span></div></div><div class="workspace-quick"><a href="#wallet"><span>✦</span><div><strong>${s.points.toLocaleString()} 积分</strong><small>查看演示账本</small></div><b>↗</b></a><a href="#earn"><span>☀</span><div><strong>每日小任务</strong><small>自主参与，慢慢积累</small></div><b>↗</b></a></div><div class="widget-title workspace-section"><h2>我分享的好发现</h2><button class="text-button" data-community="compose">＋ 新动态</button></div>${own.length?own.map(p=>postCard(p)).join(''):'<div class="empty-state"><span>✎</span><h3>每个人，都有值得分享的发现。</h3><p>写下一次好购物，或分享一个省钱小技巧。</p><button class="button small" data-community="compose">发布第一条动态 ↗</button></div>'}<div class="workspace-tools"><button data-community="export">导出我的本机社区数据 ↗</button><button data-community="recycle">查看隐藏与撤回内容 ↗</button></div>`,false)}
function settings(){return layout(`<div class="feed-heading"><div><p class="section-kicker">MAKE YOURSELF AT HOME</p><h1>个人设置</h1><p>让这个小空间，更像你。</p></div></div><section class="panel profile-form-panel"><h2>我的社区资料</h2><p>昵称与介绍仅保存到此设备，不是已注册账户。</p><form id="community-profile"><div class="field"><label for="profile-name">显示昵称</label><input id="profile-name" value="${esc(state.name)}" maxlength="24" minlength="2" required></div><div class="field"><label for="profile-bio">个人简介</label><textarea id="profile-bio" maxlength="120">${esc(state.bio)}</textarea></div><fieldset class="avatar-picker"><legend>选择头像颜色</legend>${[['lavender','薰衣草'],['mint','薄荷绿'],['peach','蜜桃橙'],['blue','晴空蓝']].map(([id,name])=>`<label><input type="radio" name="avatar" value="${id}" ${state.avatar===id?'checked':''}>${avatar(state.name,id)}<span>${name}</span></label>`).join('')}</fieldset><p class="form-error" id="profile-error" role="alert"></p><button class="button" type="submit">保存个人资料 ↗</button></form></section><section class="panel settings-notice"><h2>隐私与账户</h2><p>社区内容保存在当前浏览器，不会自动同步到其他设备。连接钱包不等于注册或签名登录。</p><div><button class="text-button" data-action="cookies">隐私偏好 ↗</button><button class="text-button" data-community="export">导出社区数据 ↗</button><button class="text-button" data-community="guidelines">社区约定 ↗</button></div></section>`,false)}
function notifications(){modal(`<p class="modal-eyebrow">YOUR LITTLE UPDATES</p><h2 class="modal-title">通知中心</h2><p class="modal-description">来自你的本机操作，没有模拟其他用户的实时消息。</p><button class="text-button" data-community="read-all">全部标为已读</button><div class="notifications-list">${state.notifications.length?state.notifications.map(n=>`<button class="notification-item ${n.read?'':'unread'}" data-community="open-notification" data-id="${esc(n.id)}"><span>✦</span><div><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small>${time(n.at)} · 本机通知</small></div></button>`).join(''):'<div class="empty-state"><span>◷</span><h3>暂时没有新的消息。</h3><p>关注品牌或发布动态后，操作记录会出现在这里。</p></div>'}</div>`)}
function report(id){modal(`<p class="modal-eyebrow">KEEP THE GOOD HERE</p><h2 class="modal-title">反馈这条动态</h2><p class="modal-description">演示反馈仅保存在本设备，不会发送给运营人员。提交后将为你隐藏这条动态，可在工作台恢复。</p><form id="community-report" data-post-id="${esc(id)}"><div class="field"><label for="report-reason">选择原因</label><select id="report-reason" required><option value="">请选择</option><option value="expired">优惠信息可能已失效</option><option value="misleading">夸大或误导性信息</option><option value="spam">重复内容或垃圾信息</option><option value="unsafe">不安全链接或敏感信息</option><option value="other">其他问题</option></select></div><button class="button wide" type="submit">保存反馈并隐藏</button></form>`)}
function manage(id){const p=get(id);if(!p?.mine)return;modal(`<p class="modal-eyebrow">YOUR DISCOVERY</p><h2 class="modal-title">管理我的动态</h2><p class="modal-description">编辑会更新本设备内容；撤回可在个人工作台恢复。</p><div class="modal-actions"><button class="button light" data-community="edit" data-id="${esc(id)}">编辑动态</button><button class="button" data-community="hide" data-id="${esc(id)}">撤回动态</button></div>`)}
function recycle(){const list=all().filter(p=>state.hidden.includes(p.id));modal(`<p class="modal-eyebrow">YOUR HIDDEN FINDS</p><h2 class="modal-title">隐藏与撤回内容</h2>${list.length?list.map(p=>`<div class="restore-item"><strong>${esc(p.title)}</strong><button class="text-button" data-community="restore" data-id="${esc(p.id)}">恢复 ↗</button></div>`).join(''):'<p class="modal-description">没有隐藏或撤回的内容。</p>'}`)}
function guidelines(){modal('<p class="modal-eyebrow">A KINDER CORNER OF THE WEB</p><h2 class="modal-title">好发现，也要好好交流。</h2><div class="modal-text"><h3>分享有用的信息</h3><p>注明优惠来源、适用条件与时效。不冒充官方合作，不发布保证收益的承诺。</p><h3>尊重与保护彼此</h3><p>不攻击他人，不公开隐私、钱包私钥或助记词。不要在不可信链接输入敏感信息。</p><h3>互动与奖励独立</h3><p>点赞、评论、发布、分享和关注不产生可提现积分。品牌发现星不可兑换 USDT。</p><h3>关于演示</h3><p>示例内容与互动不代表真实用户活动。发布、评论、反馈和资料仅保存在当前设备；正式社区需要登录、服务端存储、审核与反滥用能力。</p></div>')}
window.MONPERKS_PAGES={feed,brands:brandPage,dashboard,settings};
function enhance(){if(app.page()==='feed')renderStream();const unread=state.notifications.filter(n=>!n.read).length;const badge=$('#community-notification-badge');if(badge){badge.textContent=unread||'';badge.hidden=!unread}if(app.page()!=='feed')$('#modal')?.classList.remove('community-dialog');const intro=$('.hero-copy');if(intro&&!$('#community-entry')){const a=document.createElement('a');a.id='community-entry';a.className='community-entry';a.href='#feed';a.innerHTML='◯ 逛逛社区动态 <span>发现大家的购物灵感 ↗</span>';intro.append(a)}}
window.addEventListener('monperks:route',enhance);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-community]');if(!b)return;const action=b.dataset.community,id=b.dataset.id;if(b.disabled)return;switch(action){case 'compose':compose();break;case 'tab':tab=id;state.tab=tab;count=5;save();refresh();break;case 'topic':channel=id;count=5;if(app.page()!=='feed')location.hash='feed';else refresh();break;case 'more':count+=5;renderStream();break;case 'follow':follow(id);break;case 'brand-feed':query=catalog.find(o=>o.id===id)?.brand||'';channel='all';tab='for-you';location.hash='feed';break;case 'detail':detail(id);break;case 'vote':{if(!get(id))return;const i=state.votes.indexOf(id);if(i>=0)state.votes.splice(i,1);else state.votes.push(id);save();if($('#modal').open)detail(id);else refresh();break}case 'bookmark':{if(!get(id))return;const i=state.saved.indexOf(id);if(i>=0)state.saved.splice(i,1);else state.saved.push(id);save();if($('#modal').open)detail(id);else refresh();toast(i>=0?'已取消收藏讨论':'讨论已加入社区收藏');break}case 'share':{const url=new URL(location.href);url.hash='feed';url.searchParams.set('post',id);try{await navigator.clipboard.writeText(url.href);toast('动态链接已复制；本机发布的内容不会跨设备共享')}catch{modal(`<p class="modal-eyebrow">SHARE A GOOD FIND</p><h2 class="modal-title">复制动态链接</h2><p class="inline-code">${esc(url.href)}</p><p class="modal-description">示例动态可通过链接定位，本机动态仅在当前浏览器可见。</p>`)}break}case 'report':report(id);break;case 'manage':manage(id);break;case 'edit':if(get(id)?.mine)compose(get(id));break;case 'hide':if(get(id)?.mine&&!state.hidden.includes(id)){state.hidden.push(id);save();closeModal();refresh();toast('动态已撤回，可在工作台恢复')}break;case 'restore':state.hidden=state.hidden.filter(x=>x!==id);save();refresh();recycle();break;case 'recycle':recycle();break;case 'remove-comment':{const rows=state.comments[b.dataset.post]||[];state.comments[b.dataset.post]=rows.filter(c=>c.id!==id||!c.mine);save();detail(b.dataset.post);break}case 'notifications':notifications();break;case 'read-all':state.notifications.forEach(n=>n.read=true);save();refresh();notifications();break;case 'open-notification':{const n=state.notifications.find(x=>x.id===id);if(n){n.read=true;save();closeModal();if(get(n.target))detail(n.target);else if(location.hash==='#'+n.target)refresh();else location.hash=n.target;enhance()}break}case 'guidelines':guidelines();break;case 'export':{const blob=new Blob([JSON.stringify({app:'MONPERKS',mode:'device-local-demo',exportedAt:new Date().toISOString(),community:state},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='monperks-community-demo.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('已导出本机社区数据，不包含钱包私钥');break}}});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='community-compose'){e.preventDefault();const title=$('#post-title').value.trim(),body=$('#post-body').value.trim(),url=$('#post-link').value.trim();if(title.length<4||body.length<10){$('#compose-error').textContent='标题至少 4 个字符，正文至少 10 个字符。';return}let link='';if(url){try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)throw Error();link=u.href}catch{$('#compose-error').textContent='请输入不含账号密码的 HTTPS 来源链接。';return}}const existing=state.posts.find(p=>p.id===f.dataset.editId),post={id:existing?.id||'local-'+crypto.randomUUID(),title,body,link,channel:$('#post-channel').value,brand:$('#post-brand').value||null,at:existing?.at||new Date().toISOString(),likes:0,mine:true};if(existing)Object.assign(existing,post);else{state.posts.unshift(post);notify('你的好发现已保存','这条动态仅在当前浏览器可见，没有向外部社区发送。',post.id)}save();tab='for-you';channel='all';query='';closeModal();if(app.page()==='feed')refresh();else location.hash='feed';toast(existing?'动态修改已保存':'已发布到本机动态，不产生积分')}else if(f.id==='community-comment'){e.preventDefault();const id=f.dataset.postId,text=$('#comment-text').value.trim();if(!get(id)||text.length<2){$('#comment-error').textContent='请输入至少 2 个字符。';return}state.comments[id]??=[];state.comments[id].push({id:crypto.randomUUID(),name:state.name,text,at:new Date().toISOString(),mine:true});notify('讨论已记录','你的评论已保存在此设备，不会发送给示例作者。',id);save();refresh();detail(id);toast('评论已保存到本设备')}else if(f.id==='community-report'){e.preventDefault();const reason=$('#report-reason').value,id=f.dataset.postId;if(!reason||!get(id))return;state.reports.push({id:crypto.randomUUID(),post:id,reason,at:new Date().toISOString()});if(!state.hidden.includes(id))state.hidden.push(id);save();closeModal();refresh();toast('反馈已在本机记录，动态已隐藏；尚未发送给运营')}else if(f.id==='community-profile'){e.preventDefault();const name=$('#profile-name').value.trim();if(name.length<2){$('#profile-error').textContent='请输入至少 2 个字符的昵称。';return}state.name=name;state.bio=$('#profile-bio').value.trim();state.avatar=f.querySelector('[name="avatar"]:checked')?.value||'lavender';save();refresh();toast('个人资料已保存到本设备')}});
document.addEventListener('input',e=>{if(e.target.id==='feed-search'){query=e.target.value.trim();count=5;renderStream()}if(e.target.id==='brand-search'){brandQuery=e.target.value.trim();const start=e.target.selectionStart;refresh();const input=$('#brand-search');input?.focus();input?.setSelectionRange(start,start)}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="reset-confirm"]')){state=fresh();tab='for-you';channel='all';query='';save();refresh()}if(e.target.closest('[data-action="close"]'))$('#modal').classList.remove('community-dialog')});
$('#modal').addEventListener('close',()=>$('#modal').classList.remove('community-dialog'));
const nav=$('.header nav');nav.insertAdjacentHTML('afterbegin','<a href="#feed" data-nav="feed">社区动态</a>');nav.insertAdjacentHTML('beforeend','<a href="#brands" data-nav="brands">品牌广场</a>');
const actions=$('.header-actions');actions.insertAdjacentHTML('afterbegin','<button class="notification-bell" data-community="notifications" aria-label="打开社区通知"><span>◷</span><b id="community-notification-badge" hidden></b></button>');
const mobile=$('.mobile-nav');mobile.insertAdjacentHTML('beforeend','<a href="#feed" data-nav="feed">◯<span>社区</span></a>');
const footer=$('.footer-main>div:nth-child(2)');footer?.insertAdjacentHTML('beforeend','<a href="#feed">社区动态</a><a href="#brands">品牌广场</a><a href="#dashboard">我的工作台</a>');
const subnav=document.createElement('div');subnav.className='workspace-navigation';subnav.innerHTML='<div class="container"><a href="#feed" data-nav="feed">◯ 社区动态</a><a href="#brands" data-nav="brands">◇ 品牌广场</a><a href="#dashboard" data-nav="dashboard">▱ 我的工作台</a><a href="#settings" data-nav="settings">⚙ 个人设置</a><span>LOCAL COMMUNITY · DEMO</span></div>';$('.header').after(subnav);
if(location.hash==='#feedWorkspace')location.hash='feed';
refresh();const deep=new URLSearchParams(location.search).get('post');if(deep){if(get(deep))detail(deep);else toast('这条动态不在本设备中；本机内容不能跨设备共享')}
})();
